Load the cached values from Sheet1 and find the first row where column A contains "Code". Remove only rows above that row that are completely blank across A:D, then write the remaining rows back into A1:D5 with None padding. This preserves non-blank rows above Code and any blank rows below it.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

ROWS = 5
COLS = 4

rows = [
    [vws.cell(row=r, column=c).value for c in range(1, COLS + 1)]
    for r in range(1, ROWS + 1)
]

def is_blank(value):
    if value is None:
        return True
    if isinstance(value, str):
        return value.strip() == ""
    return False

def is_blank_row(row):
    return all(is_blank(v) for v in row)

code_row = None
for i, row in enumerate(rows, start=1):
    if not is_blank(row[0]) and str(row[0]).strip() == "Code":
        code_row = i
        break

kept_rows = []
for i, row in enumerate(rows, start=1):
    if code_row is not None and i < code_row and is_blank_row(row):
        continue
    kept_rows.append(row)

for r in range(1, ROWS + 1):
    for c in range(1, COLS + 1):
        if r <= len(kept_rows):
            value = kept_rows[r - 1][c - 1]
        else:
            value = None

        if isinstance(value, str):
            value = value.strip()
            if value == "":
                value = None

        ws.cell(row=r, column=c).value = value

wb.save(OUT)

print("code_row:", code_row)
print("kept_rows:", len(kept_rows))
for row in kept_rows:
    print(row)
